import unittest
from unittest.mock import patch
from stress_pkg.interval_policy import validate_interval

from stress_pkg.z_intervals import merge_intervals


class IntervalAcceptanceTests(unittest.TestCase):
    def test_touching_chains_and_overlaps_form_maximal_ranges(self) -> None:
        self.assertEqual(
            merge_intervals([(5, 8), (1, 3), (3, 5), (4, 6), (9, 9)]),
            [(1, 8)],
        )
        self.assertEqual(
            merge_intervals([(-5, -2), (-2, 0), (4, 7), (6, 9), (12, 12)]),
            [(-5, 0), (4, 9)],
        )

    def test_one_pass_generator_and_duplicate_semantics(self) -> None:
        class OneShot:
            def __init__(self) -> None:
                self.used = False

            def __iter__(self):
                if self.used:
                    raise AssertionError("intervals consumed more than once")
                self.used = True
                yield (8, 10)
                yield (9, 11)
                yield (11, 12)
                yield (8, 10)

        intervals = OneShot()
        self.assertEqual(merge_intervals(intervals), [(8, 12)])
        self.assertTrue(intervals.used)

    def test_invalid_rows_are_rejected_even_after_valid_rows(self) -> None:
        invalid_rows = ([1, 2], (True, 3), (4, 3))
        for invalid in invalid_rows:
            with self.subTest(interval=invalid):
                with self.assertRaisesRegex(ValueError, "^invalid interval$"):
                    merge_intervals([(0, 1), invalid])  # type: ignore[list-item]

    def test_empty_input_and_all_empty_intervals(self) -> None:
        self.assertEqual(merge_intervals(iter(())), [])
        self.assertEqual(merge_intervals([(2, 2), (-1, -1)]), [])

    def test_validator_is_called_once_per_row_including_empty_ranges(self) -> None:
        rows = [(2, 2), (1, 3), (3, 4), (1, 3)]
        with patch("stress_pkg.z_intervals.validate_interval", wraps=validate_interval) as check:
            self.assertEqual(merge_intervals(iter(rows)), [(1, 4)])
        self.assertEqual([call.args[0] for call in check.call_args_list], rows)

