import unittest

from stress_pkg.interval_policy import validate_interval
from stress_pkg.z_intervals import merge_intervals


class IntervalRegressionTests(unittest.TestCase):
    def test_unsorted_overlapping_ranges(self) -> None:
        self.assertEqual(
            merge_intervals([(9, 12), (5, 8), (1, 4), (2, 3), (10, 11)]),
            [(1, 4), (5, 8), (9, 12)],
        )

    def test_duplicate_and_empty_ranges_from_generator(self) -> None:
        intervals = (item for item in [(4, 6), (4, 6), (2, 2), (-4, -1)])
        self.assertEqual(merge_intervals(intervals), [(-4, -1), (4, 6)])
        self.assertEqual(merge_intervals(iter(())), [])

    def test_dependency_validates_exact_integer_pairs(self) -> None:
        invalid = ([1, 2], (True, 3), (4, 3))
        for interval in invalid:
            with self.subTest(interval=interval):
                with self.assertRaisesRegex(ValueError, "^invalid interval$"):
                    validate_interval(interval)

